    [Theory]
    [MemberData(nameof(RecordedImports))]
    public void Recorded_imports_match_or_refuse_unapproved_normalization(string caseId, string inputHex,
        string microsoftHex, bool refuse)
    {
        Assert.False(string.IsNullOrWhiteSpace(caseId));
        const SecurityMasks all = SecurityMasks.Owner | SecurityMasks.Group | SecurityMasks.Dacl | SecurityMasks.Sacl;
        var bytes = Convert.FromHexString(inputHex);
        var recorded = Convert.FromHexString(microsoftHex);
        var source = SecurityDescriptor.Parse(bytes, all);
        if (refuse)
        {
            Assert.NotEqual(inputHex, microsoftHex); // observed Microsoft normalization is real
            Assert.Throws<InvalidOperationException>(() => MicrosoftObservableProjector.Project(source));
        }
        else
        {
            var projected = MicrosoftObservableProjector.Project(source);
            Assert.Equal(recorded, projected.GetBinaryForm());
            Assert.Equal(recorded, MicrosoftObservableProjector.Project(projected).GetBinaryForm());
        }
        Assert.Equal(bytes, source.GetBinaryForm());
    }

    [Fact]
    public void Noncanonical_known_dacl_preserves_order_and_refuses_unproved_normalization()
    {
        var aces = new[] { Make(5, 0), Make(0, 0), Make(1, 0), Make(6, 16), Make(1, 16) };
        var raw = CoreAcl.Read(Acl(4, aces));
        Assert.Equal(aces, MicrosoftObservableProjector.ProjectAcl(raw, true).Aces
            .Select(a => a.RawBytes.ToArray()).ToArray());
        var inactive = CoreAcl.Read(Acl(4, Make(0, 0), Make(1, 0), Make(0, 8)));
        Assert.Throws<InvalidOperationException>(() => MicrosoftObservableProjector.ProjectAcl(inactive, true));
        Assert.Equal(3, inactive.Aces.Count);
    }

    [Fact]
    public void Explicit_sid_order_is_projected_but_inherited_order_is_preserved()
    {
        foreach (var type in new byte[] { 0, 1, 2, 5, 6, 7 })
        {
            var audit = type is 2 or 7;
            byte[] Create(byte[] sid, bool inherited) => type >= 5
                ? ObjAce(type, (byte)((audit ? 0x40 : 0) | (inherited ? 0x10 : 0)), 16, 1, G1, null, sid)
                : Ace(type, (byte)((audit ? 0x40 : 0) | (inherited ? 0x10 : 0)), 16, sid);
            var decreasing = new[] { Create(U2, false), Create(U1, false) };
            var raw = CoreAcl.Read(Acl(4, decreasing));
            Assert.Equal(decreasing.AsEnumerable().Reverse().ToArray(), MicrosoftObservableProjector.ProjectAcl(raw, !audit).Aces.Select(a => a.RawBytes.ToArray()).ToArray());
            Assert.Equal(decreasing, raw.Aces.Select(a => a.RawBytes.ToArray()).ToArray());
            var inherited = new[] { Create(U2, true), Create(U1, true) };
            Assert.Equal(inherited, MicrosoftObservableProjector.ProjectAcl(CoreAcl.Read(Acl(4, inherited)), !audit)
                .Aces.Select(a => a.RawBytes.ToArray()).ToArray());
            var ordered = new[] { Create(U1, false), Create(U2, false) };
            Assert.Equal(ordered, MicrosoftObservableProjector.ProjectAcl(CoreAcl.Read(Acl(4, ordered)), !audit)
                .Aces.Select(a => a.RawBytes.ToArray()).ToArray());
        }
    }

    private static byte[] Make(byte type, byte flags) => type >= 5
        ? ObjAce(type, flags, 16, 3, G1, G2, U1)
        : Ace(type, flags, 16, U1);
}
